1	package settings
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io/fs"
10		"log/slog"
11		"os"
12		"path/filepath"
13		"runtime"
14		"strings"
15	
16		"github.com/bmatcuk/doublestar/v4"
17		"github.com/entireio/cli/cmd/entire/cli/gitremote"
18		"github.com/entireio/cli/cmd/entire/cli/logging"
19		"github.com/entireio/cli/cmd/entire/cli/paths"
20		"github.com/entireio/cli/internal/entireclient/userdirs"
21	)
22	
23	// UserSettingsFileName is the basename of the user-global settings file inside
24	// userdirs.Config(). It sits beside contexts.json and holds machine-wide
25	// configuration that is not tied to any repository.
26	const UserSettingsFileName = "settings.json"
27	
28	// caseInsensitivePaths folds exclude_paths matching on macOS and Windows,
29	// whose default filesystems are case-insensitive: the worktree root's casing
30	// varies with how the agent was launched.
31	var caseInsensitivePaths = runtime.GOOS == "darwin" || runtime.GOOS == "windows"
32	
33	// GlobalConfig is the "global" section of the user-global settings file.
34	// It controls global auto-enable: tracking agent sessions in repositories
35	// that have no repo-level Entire setup.
36	type GlobalConfig struct {
37		// Enabled turns global mode on. Both true and false count as configured.
38		Enabled bool `json:"enabled"`
39	
40		// ExcludePaths are ~-expanded doublestar globs matched against a
41		// repository's worktree root. Any match excludes that worktree.
42		ExcludePaths []string `json:"exclude_paths,omitempty"`
43	
44		// ExcludeOrigins are doublestar globs matched against the origin remote
45		// URL normalized to host/owner/repo. A repo without an origin matches
46		// no origin pattern. Origins stored via git insteadOf shorthands (e.g.
47		// gh:acme/widgets) normalize to the shorthand form, not the expanded
48		// host — patterns match what git config stores.
49		ExcludeOrigins []string `json:"exclude_origins,omitempty"`
50	}
51	
52	// UserSettings is the root of the user-global settings file.
53	type UserSettings struct {
54		Global *GlobalConfig `json:"global,omitempty"`
55	}
56	
57	// LoadUserSettings reads the user-global settings file. A missing file is not
58	// an error: it returns an empty UserSettings (Global == nil, meaning the
59	// global tier is unconfigured). A malformed file returns an error; callers on
60	// the hook path must treat that as global-off (fail closed).
61	func LoadUserSettings(_ context.Context) (*UserSettings, error) {
62		// Deliberately plain os.ReadFile: readConfined/os.Root rejects absolute
63		// symlinks, and ~/.config/entire/settings.json is commonly symlinked by
64		// dotfile managers — with fail-closed semantics that would silently
65		// disable global mode.
66		data, err := os.ReadFile(filepath.Join(userdirs.Config(), UserSettingsFileName))
67		if err != nil {
